from functools import lru_cache
nodes=list('ABCDEFGH')
idx={n:i for i,n in enumerate(nodes)}
edges=[('A','D'),('A','E'),('B','D'),('B','F'),('C','E'),('C','F'),('D','G'),('E','G'),('E','H'),('F','H')]
pre=[0]*len(nodes)
for u,v in edges:
    pre[idx[v]] |= 1<<idx[u]
@lru_cache(None)
def dp(mask):
    if mask==(1<<len(nodes))-1:
        return 1
    total=0
    for i in range(len(nodes)):
        if not (mask>>i)&1 and pre[i]&~mask==0:
            total += dp(mask|1<<i)
    return total
print(dp(0))
