from functools import lru_cache
verts = list('ABCDEFGHIJKL')
idx = {v:i for i,v in enumerate(verts)}
edges = [('A','H'),('B','G'),('B','H'),('B','I'),('B','L'),('C','D'),('C','F'),('C','G'),('C','J'),('D','L'),('E','G'),('E','J'),('E','L'),('F','I'),('H','K'),('H','L'),('J','K'),('K','L')]
pre = [0]*len(verts)
for u,v in edges:
    pre[idx[v]] |= 1<<idx[u]
N=len(verts)
ALL=(1<<N)-1
@lru_cache(None)
def dp(mask):
    if mask==ALL:
        return 1
    total=0
    for i in range(N):
        if not (mask>>i)&1 and (pre[i] & ~mask)==0:
            total += dp(mask | (1<<i))
    return total
