import random
from functools import lru_cache
random.seed(40)

def count_ham_paths(n, edges, s, t):
    adj=[0]*n
    for u,v in edges:
        adj[u]|=1<<v
        adj[v]|=1<<u
    @lru_cache(None)
    def dp(mask,v):
        if mask==(1<<n)-1:
            return 1 if v==t else 0
        total=0
        m=adj[v] & ~mask
        while m:
            b=m & -m
            u=b.bit_length()-1
            total += dp(mask|b,u)
            m -= b
        return total
    return dp(1<<s,s), dp.cache_info().currsize

for trial in range(5000):
    n=20
    edges=[]
    # random tree backbone to ensure connectivity
    for v in range(1,n):
