    poss=[(i,j) for i in range(n) for j in range(i+1,n) if (i,j) not in edges]
    random.shuffle(poss)
    edges += poss[:14]
    c,states=count_ham_paths(n,edges,0,n-1)
    if 50 < c < 10000 and states < 2000000 and c%2 and c%3 and c%5 and c%7:
        print(c, states)
        print(edges)
