        total=0
        prevmask=mask ^ (1<<v)
        m = inmask[v] & prevmask
        while m:
            b=m & -m
            u=b.bit_length()-1
            total += f(prevmask,u)
            m -= b
        return total
    total=0
    mask=FULL
    for v in range(1,n):
        if (out[v]>>start)&1:
            total += f(mask,v)
    return total, f.cache_info().currsize

