def det_bareiss(M):
    A=[row[:] for row in M]
    n=len(A)
    if n==0: return 1
    sign=1
    prev=1
    for k in range(n-1):
        if A[k][k]==0:
            for i in range(k+1,n):
                if A[i][k]!=0:
                    A[k],A[i]=A[i],A[k]
                    sign*=-1
                    break
